//! R14: the stop a console gives, on Windows. A user at a console presses
//! Ctrl+Break, or a launcher sends it as openIVR's `run_all.py` does to its
//! backend; oxrtc must stop as it does on SIGTERM: exit 0 within the 5 s
//! openIVR allows, listeners and FFmpeg gone, "stopped" logged.
//!
//! The event is generated by a child process (`common/console_parent.py`):
//! only a process on the same console can send one, and the workspace forbids
//! the unsafe call. The child starts oxrtc in a console group of its own, the
//! way `go2rtc_manager.py` starts the media server, and sends CTRL_BREAK to
//! that group's id. It has a hidden console of its own, so nothing reaches the
//! terminal running the tests. What openIVR's `ManagedServer.stop()` sends
//! (`TerminateProcess`) is `e2e.rs`'s `stop`. Skipped (and passed) when
//! FFmpeg, go2rtc or Python is absent, like `e2e.rs`.
#![cfg(windows)]
#![allow(missing_docs, clippy::unwrap_used, clippy::expect_used, clippy::panic, clippy::indexing_slicing)]

mod common;

use std::process::Stdio;
use std::time::{Duration, Instant};

use common::launch::*;
use common::*;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::process::{Child, ChildStdin, Command};
use tokio::sync::mpsc;

/// `CREATE_NO_WINDOW`: a console of its own, without a window.
const CREATE_NO_WINDOW: u32 = 0x0800_0000;

/// The launcher (`console_parent.py`) and what it says.
struct Launcher {
    child: Child,
    stdin: ChildStdin,
    lines: mpsc::UnboundedReceiver<String>,
    /// What oxrtc wrote, as relayed.
    log: Vec<String>,
    /// Held so that a failed test ends the launcher and what it started.
    _job: win32job::Job,
}

impl Launcher {
    fn start(python: &std::path::Path, script: &std::path::Path, config: &std::path::Path, mode: &str) -> Self {
        let mut child = Command::new(python)
            .arg(script)
            .arg(env!("CARGO_BIN_EXE_oxrtc"))
            .arg(config)
            .arg(mode)
            .creation_flags(CREATE_NO_WINDOW)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .kill_on_drop(true)
            .spawn()
            .unwrap();
        let job = kill_on_close_job(&child);
        let stdin = child.stdin.take().unwrap();
        let mut stdout = BufReader::new(child.stdout.take().unwrap()).lines();
        let (sender, lines) = mpsc::unbounded_channel();
        tokio::spawn(async move {
            while let Ok(Some(line)) = stdout.next_line().await {
                eprintln!("launcher| {line}");
                if sender.send(line).is_err() {
                    break;
                }
            }
        });
        Self { child, stdin, lines, log: Vec::new(), _job: job }
    }

    /// The text after `word` on the launcher's next line that starts with it;
    /// oxrtc's lines (`LOG ...`) met on the way are kept.
    async fn next(&mut self, word: &str, within: Duration) -> String {
        let deadline = Instant::now() + within;
        loop {
            let left = deadline.saturating_duration_since(Instant::now());
            let line = tokio::time::timeout(left, self.lines.recv())
                .await
                .unwrap_or_else(|_| panic!("no `{word}` line from the launcher within {within:?}: {:#?}", self.log))
                .unwrap_or_else(|| panic!("the launcher ended before `{word}`: {:#?}", self.log));
            if let Some(log) = line.strip_prefix("LOG ") {
                self.log.push(log.to_owned());
            } else if let Some(rest) = line.strip_prefix(word) {
                return rest.trim().to_owned();
            }
        }
    }

    async fn say(&mut self, line: &str) {
        self.stdin.write_all(format!("{line}\n").as_bytes()).await.unwrap();
        self.stdin.flush().await.unwrap();
    }
}

async fn is_listening(addr: std::net::SocketAddr) -> bool {
    // A listener on loopback accepts within milliseconds; a refused connect
    // takes about 2 s on Windows (it retries), so a slow answer means "gone".
    matches!(tokio::time::timeout(Duration::from_millis(500), tokio::net::TcpStream::connect(addr)).await, Ok(Ok(_)))
}

/// Starts oxrtc under the launcher with a transcode held (one FFmpeg), and
/// returns what the test needs to check the rest.
struct Run {
    launcher: Launcher,
    ports: Ports,
    ffmpeg: Vec<u32>,
    camera: FakeCamera,
    dir: std::path::PathBuf,
}

async fn run(tools: &Tools, python: &std::path::Path, mode: &str) -> Run {
    let camera = FakeCamera::start(tools).await;
    let dir = temp_dir("ctrl-break");
    let ports = Ports::free();
    let config = transcode_config(&dir, tools, &camera, &ports);
    let script = dir.join("console_parent.py");
    std::fs::write(&script, include_str!("common/console_parent.py")).unwrap();
    let mut launcher = Launcher::start(python, &script, &config, mode);
    let pid: u32 = launcher.next("PID", Duration::from_secs(20)).await.parse().unwrap();
    wait_healthy(ports.api()).await;
    let reply =
        Request::new("PUT", "/api/preload?src=cam_small&video=").auth(API_USER, API_PASS).send(ports.api()).await;
    assert_eq!(reply.status, 200, "preload of the transcode: {}", reply.text());
    let deadline = Instant::now() + Duration::from_secs(10);
    let ffmpeg = loop {
        let children = ffmpeg_children(pid);
        if !children.is_empty() {
            break children;
        }
        assert!(Instant::now() < deadline, "no FFmpeg under oxrtc while a transcode is held");
        tokio::time::sleep(Duration::from_millis(100)).await;
    };
    Run { launcher, ports, ffmpeg, camera, dir }
}

impl Run {
    async fn finish(mut self) {
        let _ = self.launcher.child.wait().await;
        self.camera.stop().await;
        remove_dir(&self.dir).await;
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn ctrl_break_to_its_group_stops_it_like_sigterm() {
    let Some(tools) = Tools::find() else { return };
    let Some(python) = find_python() else { return };
    let mut run = run(&tools, &python, "own").await;

    let started = Instant::now();
    run.launcher.say("break").await;
    let ended = run.launcher.next("EXIT", Duration::from_secs(15)).await;
    let (code, seconds) = ended.split_once(' ').unwrap();
    assert_eq!(code, "0", "a console stop exits 0: {:#?}", run.launcher.log);
    let seconds: f64 = seconds.parse().unwrap();
    assert!(seconds < 5.0, "stopped in {seconds} s, past the 5 s openIVR allows");

    for addr in [run.ports.api(), run.ports.rtsp()] {
        while is_listening(addr).await {
            assert!(started.elapsed() < Duration::from_secs(5), "{addr} still listening 5 s after the break");
            tokio::time::sleep(Duration::from_millis(50)).await;
        }
    }
    while !still_running(&run.ffmpeg).is_empty() {
        assert!(started.elapsed() < Duration::from_secs(5), "FFmpeg {:?} outlived the stop by 5 s", run.ffmpeg);
        tokio::time::sleep(Duration::from_millis(50)).await;
    }
    eprintln!("stopped by Ctrl+Break in {seconds} s, with {} FFmpeg", run.ffmpeg.len());
    let has = |needle: &str| run.launcher.log.iter().any(|l| l.contains(needle));
    assert!(has(" INF [app] stopping"), "{:#?}", run.launcher.log);
    assert!(has(" INF [app] stopped"), "{:#?}", run.launcher.log);
    run.finish().await;
}

/// A break is addressed to a group: another group's is not oxrtc's, which is
/// why `go2rtc_manager.py` starts the media server in a group of its own (the
/// backend's own stop must not end it, first). oxrtc keeps serving.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn ctrl_break_to_another_group_does_not_reach_it() {
    let Some(tools) = Tools::find() else { return };
    let Some(python) = find_python() else { return };
    let mut run = run(&tools, &python, "other").await;

    run.launcher.say("break").await;
    let bystander = run.launcher.next("BYSTANDER", Duration::from_secs(15)).await;
    assert_ne!(bystander, "running", "the break was sent to the bystander's group, and ended it");
    tokio::time::sleep(Duration::from_millis(500)).await;
    let reply = Request::new("GET", "/api").auth(API_USER, API_PASS).send(run.ports.api()).await;
    assert_eq!(reply.status, 200, "oxrtc still serves after a break to another group");
    assert!(!still_running(&run.ffmpeg).is_empty(), "its FFmpeg still runs");
    assert!(!run.launcher.log.iter().any(|l| l.contains(" INF [app] stopping")), "{:#?}", run.launcher.log);
    run.launcher.say("end").await;
    run.finish().await;
}

/// Only a socket bound to the port holds it: connections that end at it or
/// wait out `TIME_WAIT` there do not (the lines of the run that failed).
#[test]
#[cfg(windows)]
fn a_connection_waiting_out_time_wait_holds_no_port() {
    let port = 27426;
    for line in [
        "  TCP    127.0.0.1:27426        127.0.0.1:51207        TIME_WAIT       0",
        "  TCP    127.0.0.1:51202        127.0.0.1:27426        TIME_WAIT       0",
        "  TCP    127.0.0.1:51203        127.0.0.1:27426        ESTABLISHED     4242",
        "  TCP    127.0.0.1:274260       0.0.0.0:0              LISTENING       4242",
        "  TCP    127.0.0.1:27426        127.0.0.1:51207        WARTEND         0",
    ] {
        assert!(!holds_port(line, port), "{line}");
    }
    for line in [
        "  TCP    127.0.0.1:27426        0.0.0.0:0              LISTENING       4242",
        "  TCP    [::]:27426             [::]:0                 LISTENING       4242",
        // netstat writes the state in the system's language.
        "  TCP    127.0.0.1:27426        0.0.0.0:0              ABHÖREN         4242",
        "  UDP    0.0.0.0:27426          *:*                                    4242",
    ] {
        assert!(holds_port(line, port), "{line}");
    }
}

/// A launch that finds its port taken says who has it (`launch::holders`):
/// the failure of CI run 44629451943 named the port and nobody.
#[test]
fn the_holder_of_a_taken_port_is_named() {
    let port = free_tcp_port();
    assert_eq!(holders(port), "", "nothing listens on a port just drawn");
    let _held = std::net::TcpListener::bind(("127.0.0.1", port)).unwrap();
    let said = holders(port);
    assert!(said.contains(&format!("127.0.0.1:{port}")), "{said}");
    assert!(said.contains(&std::process::id().to_string()), "the owner's process id: {said}");
    assert!(said.contains("ctrl_break"), "the owner's name: {said}");
}
